This Terraform configuration creates an AWS RDS MySQL database instance with a randomly generated database identifier and password. It uses the default VPC and its subnets, creates a security group for MySQL access, creates an RDS subnet group, and provisions the RDS instance with generated credentials.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the RDS instance will be created."
  type        = string
  default     = "us-east-1"
}

